import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Whole-graph degree of each candidate, divided by the maximum degree among candidates."""
    d = np.asarray(degree, dtype=float)
    if d.size == 0:
        return np.zeros(0)
    m = max(float(d.max()), 1.0)
    return d / m

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Max share of a candidate's coloured neighbours that share one colour (0 if none coloured)."""
    k = neighbor_colors.shape[0]
    if neighbor_colors.shape[1] == 0:
        return np.zeros(k)
    row_sum = neighbor_colors.sum(axis=1).astype(float)
    row_max = neighbor_colors.max(axis=1).astype(float)
    denom = np.maximum(row_sum, 1.0)
    return np.where(row_sum > 0, row_max / denom, 0.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Density of candidate's uncoloured neighbourhood (triangles / possible pairs), blended with coloured-neighbour pressure (fraction of used colours touched)."""
    k = adjacency.shape[0]
    if k == 0:
        return np.zeros(0)
    # uncoloured degree and triangle count via a single matrix product
    deg_u = adjacency.sum(axis=1).astype(float)
    a2 = adjacency @ adjacency  # int matrix product, cheap-ish
    tri = np.einsum('ij,ij->i', a2, adjacency).astype(float) * 0.5
    denom = deg_u * (deg_u - 1.0)
    density = np.where(denom > 1e-12, 2.0 * tri / np.maximum(denom, 1e-12), 0.0)

    if neighbor_colors.shape[1] > 0:
        touched = (neighbor_colors > 0).sum(axis=1).astype(float)
        c = float(neighbor_colors.shape[1])
        pressure = touched / c
    else:
        pressure = np.zeros(k)

    raw = density * (0.5 - pressure) + 0.5 * pressure
    return np.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """For candidates that would open a new colour, how many uncoloured neighbours they block; else 0."""
    k, c = neighbor_colors.shape
    if c == 0:
        # everyone opens a new colour at the first decision: use uncoloured neighbourhood size
        uncolored_deg = adjacency.sum(axis=1).astype(float)
        return uncolored_deg / (k + 1.0)
    blocked = (neighbor_colors > 0).any(axis=1)
    opens_new = ~blocked
    uncolored_deg = adjacency.sum(axis=1).astype(float)
    n = k + color_sizes.sum()
    return np.where(opens_new, uncolored_deg / (n + 1.0), 0.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Size of the class a candidate would actually join (first free colour), normalised by the largest class; -1 if it would open a new colour."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    free = (neighbor_colors == 0)
    has_free = free.any(axis=1)
    j = np.where(has_free, free.argmax(axis=1), c)
    join = np.where(j < c, color_sizes[np.minimum(j, c - 1)], 0.0)
    gain = join / np.maximum(color_sizes.max(), 1)
    return np.where(j < c, gain, -1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Negative size-weighted share of a candidate's neighbourhood lying in existing colour classes."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    w = color_sizes / np.maximum(color_sizes.sum(), 1.0)
    conflict = neighbor_colors.astype(float) @ w
    return -conflict / np.maximum(degree.astype(float), 1.0)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Saturation weighted by exponential colour scarcity 2^-free, times (0.5+0.5*scaled uncoloured degree)."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    touched = (neighbor_colors > 0).sum(1).astype(float)
    free = c - touched
    sat = touched / (c + 1.0)
    scarcity = np.exp2(-free)
    udeg = adjacency.sum(1).astype(float)
    dscale = udeg / (udeg.max() + 1.0)
    return sat * scarcity * (0.5 + 0.5 * dscale)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Max-class share of a candidate's coloured neighbours, gated by low saturation and scaled by coloured-neighbour strength."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    coloured = neighbor_colors.sum(1).astype(float)
    touched = (neighbor_colors > 0).sum(1).astype(float)
    dom = neighbor_colors.max(1).astype(float)
    conc = dom / (coloured + 1.0)
    gate = 1.0 - touched / (c + 1.0)
    strength = coloured / (coloured.max() + 1.0)
    return conc * gate * (0.5 + 0.5 * strength)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Number of still-uncoloured neighbours, normalised by the max and centred."""
    udeg = adjacency.sum(axis=1).astype(float)
    v = udeg / (udeg.max() + 1.0)
    return v - v.mean()

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Normalised saturation times normalised count of still-legal existing colours."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    sat = (neighbor_colors > 0).sum(axis=1).astype(float)
    free = c - sat
    return (sat / c) * (free / c)

import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Excess of the max share of a candidate's coloured neighbours on one colour over that colour's global prevalence."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    nc = neighbor_colors.astype(float)
    tot = nc.sum(axis=1)
    maxshare = np.where(tot > 0, nc.max(axis=1) / np.maximum(tot, 1.0), 0.0)
    top = nc.argmax(axis=1)
    ncol = color_sizes.sum()
    glob = color_sizes[top] / max(ncol, 1)
    return np.where(tot > 0, maxshare - glob, 0.0)

