    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    free = (neighbor_colors == 0)                                   # (k, c) still-legal existing colours
    first = np.where(free.any(axis=1), free.argmax(axis=1), c).astype(float)  # colour it would get, c = new colour
    return -first / float(c)

