import numpy as np

def feature(neighbor_colors, adjacency, degree, color_sizes):
    """Heaviest single-colour share of a candidate's coloured neighbours, weighted by 1/(1+index of the colour it would take)."""
    k, c = neighbor_colors.shape
    if c == 0:
        return np.zeros(k)
    nc = neighbor_colors.astype(float)
    total = nc.sum(axis=1)
    conc = np.where(total > 0, nc.max(axis=1) / np.maximum(total, 1.0), 0.0)   # heaviest single colour share
    free = (neighbor_colors == 0)
    first = np.where(free.any(axis=1), free.argmax(axis=1), c).astype(float)  # colour it would get
    low = 1.0 / (1.0 + first)
    return np.clip(conc * low, 0.0, 1.0)

